/** What verifyVectors reports (the shape scripts/run-golden-vectors.mts reads). */
export interface VerifyReport {
  // The set id.
  setId: string;
  // Vectors run.
  total: number;
  // Vectors whose pinned fields matched.
  passed: number;
  // The ones that did not, with the first difference.
  failures: { id: string; reason: string }[];
}

/** Run every vector and compare the whole result byte for byte. */
export function verifyVectors(): VerifyReport {
  // The failures.
  const failures: VerifyReport["failures"] = [];
  // Each vector.
  for (const v of VECTORS) {
    // Run.
    const got = JSON.stringify(run(v.input));
    // Expected.
    const want = JSON.stringify(v.expect);
    // Compare.
    if (got !== want) {
      // The first differing position, for the report.
      let i = 0;
      while (i < got.length && i < want.length && got[i] === want[i]) i++;
      // Record.
      failures.push({ id: v.id, reason: `differs at ${i}: got ...${got.slice(Math.max(0, i - 40), i + 60)}... want ...${want.slice(Math.max(0, i - 40), i + 60)}...` });
    }
  }
  // Report.
  return { setId: GOLDEN_VECTOR_SET_ID, total: VECTORS.length, passed: VECTORS.length - failures.length, failures };
}
